  await page.goto("/");
  await page.getByRole("radio", { name: "Student" }).check();

  const textboxes = page.getByRole("textbox");
  await expect(textboxes).toHaveCount(6);
  for (const label of ["First name", "Last name", "Email", "Study institution", "Study programme", "Student ID"]) {
    await expect(page.getByLabel(label, { exact: true })).toBeVisible();
  }
  await expect(page.getByLabel("Organization / institution", { exact: true })).toHaveCount(0);

  const shown: string[] = [];
