    const boxes = page.getByRole("group", { name: group }).getByRole("checkbox");
    for (const box of await boxes.all()) {
      shown.push(
        (
          await box.evaluate(
            (el) => (el as HTMLInputElement).labels?.[0]?.textContent ?? el.getAttribute("aria-label") ?? "",
          )
        ).trim(),
      );
    }
  }
  const studentOptions = config.options.filter((o) => o.availableTo.includes("STUDENT")).map((o) => o.name);
  expect(shown.sort()).toEqual([...studentOptions].sort());

  await page.getByLabel("First name", { exact: true }).fill("Bor");
  await page.getByLabel("Last name", { exact: true }).fill("Kranjc");
  await page.getByLabel("Email", { exact: true }).fill(email);
  await page.getByLabel("Study institution", { exact: true }).fill("University of Maribor");
  await page.getByLabel("Study programme", { exact: true }).fill("Computer Science");
  await page.getByLabel("Student ID", { exact: true }).fill("63210001");
  const options = await tickOnePerCategory(page);
  await giveConsentsAndPassCaptcha(page, config);
  await page.getByRole("button", { name: "Register" }).click();

  const status = page.getByRole("status");
  await expect(status.getByRole("heading", { name: "Registration received" })).toBeVisible();
  await expect(status).toContainText("Thank you, Bor Kranjc.");
  for (const name of options) {
    await expect(status.getByRole("list", { name: "Selected options" })).toContainText(name);
  }

  const rows = sql(
    `SELECT id, registration_type, study_institution, study_programme, student_id FROM registration WHERE email = ${sqlText(email)}`,
  );
  expect(rows).toHaveLength(1);
  const [id, ...values] = rows[0];
  expect(values).toEqual(["STUDENT", "University of Maribor", "Computer Science", "63210001"]);
  expect(JSON.parse(jsonCopy(id))).toMatchObject({ id, type: "STUDENT", studentId: "63210001" });

  const mails = await mailsMentioning(email, 2);
  expect(mails.some((m) => m.To.some((r) => r.Address === email))).toBe(true);
  expect(
    mails.some(
      (m) => !m.To.some((r) => r.Address === email) && m.Attachments.some((a) => a.FileName === `registration-${id}.json`),
    ),
  ).toBe(true);
});

