  const chooseType = (next: RegistrationType) => {
    setType(next);
    setOptionIds((ids) =>
      ids.filter((id) => config.options.some((o) => o.id === id && o.availableTo.includes(next))),
    );
  };
  const toggle = (list: string[], id: string, on: boolean) =>
    on ? [...list, id] : list.filter((x) => x !== id);

  const failSubmission = () => {
    setToken("");
    setResetCount((n) => n + 1);
  };

  const onSubmit = async (event: FormEvent) => {
    event.preventDefault();
    const clientErrors = validate({ type, values, consents, recaptchaToken: token }, config.consents);
