  void undeclaredSmallBodyIsReplayedToTheApplication() throws Exception {
    AtomicReference<HttpServletRequest> seen = new AtomicReference<>();
    byte[] body = "čšž{}".getBytes(StandardCharsets.UTF_8);

    new BodySizeLimitFilter(64)
        .doFilter(
