import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import si.konferenca.registration.RegistrationProperties;

class RecaptchaVerifierTest {

  private HttpServer server;
  private final AtomicReference<String> lastForm = new AtomicReference<>();
  private final AtomicReference<String> lastContentType = new AtomicReference<>();
  private volatile int status = 200;
  private volatile String answer = "{\"success\": true}";

  @BeforeEach
  void startServer() throws IOException {
    server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
    server.createContext(
        "/verify",
        exchange -> {
          lastForm.set(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
          lastContentType.set(exchange.getRequestHeaders().getFirst("Content-Type"));
          byte[] body = answer.getBytes(StandardCharsets.UTF_8);
          exchange.sendResponseHeaders(status, body.length);
          try (OutputStream out = exchange.getResponseBody()) {
            out.write(body);
          }
        });
    server.start();
  }

  @AfterEach
  void stopServer() {
    server.stop(0);
  }

  private RecaptchaVerifier verifier(boolean testMode, String secret, String url) {
    return new RecaptchaVerifier(
        new RegistrationProperties(
            "C",
            "classpath:conference.json",
            Path.of("x"),
            new RegistrationProperties.Mail("f@example.com", List.of()),
            new RegistrationProperties.Recaptcha(testMode, "site", secret, URI.create(url)),
            new RegistrationProperties.Organizer("u", "p", true),
            new RegistrationProperties.Cors(List.of()),
            new RegistrationProperties.RateLimit(1, 1, 1),
            100));
  }

  private String url() {
    return "http://127.0.0.1:" + server.getAddress().getPort() + "/verify";
  }

  @Test
  void testModeAcceptsOnlyTheTestTokenWithoutNetwork() {
    RecaptchaVerifier verifier = verifier(true, "secret", url());

    assertThat(verifier.verify(RecaptchaVerifier.TEST_MODE_TOKEN, "1.2.3.4")).isTrue();
    assertThat(verifier.verify("test-mode-token ", "1.2.3.4")).isFalse();
    assertThat(verifier.verify("anything", null)).isFalse();
    assertThat(lastForm.get()).isNull();
  }

  @Test
  void productionPathPostsSecretTokenAndClientAddress() {
    assertThat(verifier(false, "s&cret", url()).verify("tok en", "1.2.3.4")).isTrue();

    assertThat(lastForm.get()).isEqualTo("secret=s%26cret&response=tok+en&remoteip=1.2.3.4");
    assertThat(lastContentType.get()).isEqualTo("application/x-www-form-urlencoded");
  }

  @Test
  void clientAddressIsOptionalAndNullSecretIsSentEmpty() {
    assertThat(verifier(false, null, url()).verify("t", null)).isTrue();
    assertThat(lastForm.get()).isEqualTo("secret=&response=t");
  }

  @Test
  void rejectedUnlessHttp200WithSuccessTrue() {
    RecaptchaVerifier verifier = verifier(false, "secret", url());
    answer = "{\"success\": false}";
    assertThat(verifier.verify("t", null)).isFalse();
    answer = "{}";
    assertThat(verifier.verify("t", null)).isFalse();
    answer = "{\"success\": \"true\"}";
    assertThat(verifier.verify("t", null)).isFalse();
    answer = "not json";
    assertThat(verifier.verify("t", null)).isFalse();
    answer = "{\"success\": true}";
    status = 500;
    assertThat(verifier.verify("t", null)).isFalse();
  }

  @Test
  void unreachableVerifierRejects() {
    server.stop(0);
    assertThat(verifier(false, "secret", url()).verify("t", null)).isFalse();
  }

  @Test
  void interruptedVerificationRejectsAndKeepsTheInterruptFlag() {
    Thread.currentThread().interrupt();
    try {
      assertThat(verifier(false, "secret", url()).verify("t", null)).isFalse();
      assertThat(Thread.currentThread().isInterrupted()).isTrue();
    } finally {
      Thread.interrupted();
    }
  }
}

package si.konferenca.registration.storage;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.UncheckedIOException;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import java.util.stream.Stream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import si.konferenca.registration.RegistrationProperties;
import si.konferenca.registration.domain.OptionCategory;
import si.konferenca.registration.domain.Registration;
import si.konferenca.registration.domain.RegistrationType;

class FileJsonCopyStoreTest {

  static final UUID ID = UUID.fromString("6f1c1b7e-2f7a-4c55-9d0e-3c1f7c2b9a10");
  static final Instant AT = Instant.parse("2026-10-13T08:00:00.120Z");

  static Registration student() {
    return new Registration(
        ID,
        AT,
        RegistrationType.STUDENT,
        "Špela",
        "Žnidaršič",
        "s@example.com",
        null,
        "Univerza",
        "Računalništvo",
        "6321",
        List.of(new Registration.SelectedOption("ws", "Workshop", OptionCategory.WORKSHOP)),
        List.of(new Registration.GivenConsent("privacy", "I agree", AT)));
  }

  static FileJsonCopyStore store(Path dir) {
    return new FileJsonCopyStore(
        new RegistrationProperties(
            "C",
            "c",
            dir,
            new RegistrationProperties.Mail("f@example.com", List.of()),
            new RegistrationProperties.Recaptcha(true, "", "", URI.create("http://x")),
            new RegistrationProperties.Organizer("u", "p", true),
            new RegistrationProperties.Cors(List.of()),
            new RegistrationProperties.RateLimit(1, 1, 1),
            100));
  }

  @Test
  void jsonCopyHasTheContractFieldsInOrderWithLfAndUnescapedText() {
    String json = new String(RegistrationJson.toBytes(student()), StandardCharsets.UTF_8);

    assertThat(json)
        .isEqualTo(
            """
            {
              "id" : "6f1c1b7e-2f7a-4c55-9d0e-3c1f7c2b9a10",
              "type" : "STUDENT",
              "registeredAt" : "2026-10-13T08:00:00.120Z",
              "firstName" : "Špela",
              "lastName" : "Žnidaršič",
              "email" : "s@example.com",
              "studyInstitution" : "Univerza",
              "studyProgramme" : "Računalništvo",
              "studentId" : "6321",
              "options" : [ {
                "id" : "ws",
                "name" : "Workshop",
                "category" : "WORKSHOP"
              } ],
              "consents" : [ {
                "id" : "privacy",
                "text" : "I agree",
                "givenAt" : "2026-10-13T08:00:00.120Z"
              } ]
            }""");
    assertThat(json).doesNotContain("\r", "organization");
  }

  @Test
  void externalCopyHasOrganizationOnly() {
    Registration external =
        new Registration(
            ID, AT, RegistrationType.EXTERNAL, "A", "B", "a@b.co", "Org", null, null, null, List.of(),
            List.of());

    String json = new String(RegistrationJson.toBytes(external), StandardCharsets.UTF_8);

    assertThat(json).contains("\"organization\" : \"Org\"", "\"options\" : [ ]");
    assertThat(json).doesNotContain("studyInstitution", "studyProgramme", "studentId");
  }

  @Test
  void writeCreatesTheDirectoryAndTheNamedFileAndReturnsItsBytes(@TempDir Path tmp) throws Exception {
    Path dir = tmp.resolve("nested/copies");

    byte[] written = store(dir).write(student());

    Path file = dir.resolve(ID + ".json");
    assertThat(Files.readAllBytes(file)).isEqualTo(written).isEqualTo(RegistrationJson.toBytes(student()));
    try (Stream<Path> files = Files.list(dir)) {
      assertThat(files).containsExactly(file);
    }
  }

  @Test
  void deleteRemovesTheCopyAndIgnoresAMissingOne(@TempDir Path tmp) {
    FileJsonCopyStore store = store(tmp);
    store.write(student());

    store.delete(ID);
    store.delete(ID);

    assertThat(tmp.resolve(ID + ".json")).doesNotExist();
  }

  @Test
  void deleteOfANonEmptyDirectoryWithTheSameNameIsOnlyLogged(@TempDir Path tmp) throws Exception {
    Files.createDirectories(tmp.resolve(ID + ".json").resolve("inside"));

    store(tmp).delete(ID);

    assertThat(tmp.resolve(ID + ".json")).isDirectory();
  }

  @Test
  void writeFailsWhenTheDirectoryIsAFileAndLeavesNoTemporaryFile(@TempDir Path tmp)
      throws Exception {
    Path notADirectory = Files.createFile(tmp.resolve("file"));

    assertThatThrownBy(() -> store(notADirectory).write(student()))
        .isInstanceOf(UncheckedIOException.class)
        .hasMessage("JSON copy could not be written");
  }

  @Test
  void failedMoveRemovesTheTemporaryFile(@TempDir Path tmp) throws Exception {
    Files.createDirectories(tmp.resolve(ID + ".json").resolve("blocks-the-move"));

    assertThatThrownBy(() -> store(tmp).write(student())).isInstanceOf(UncheckedIOException.class);

    try (Stream<Path> files = Files.list(tmp)) {
      assertThat(files).containsExactly(tmp.resolve(ID + ".json"));
    }
  }
}

