import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.mock.http.MockHttpInputMessage;
import org.springframework.web.HttpMediaTypeNotSupportedException;
import org.springframework.web.HttpRequestMethodNotSupportedException;
import org.springframework.web.servlet.resource.NoResourceFoundException;
import si.konferenca.registration.domain.ConferenceCatalog;
import si.konferenca.registration.domain.ConferenceOption;
import si.konferenca.registration.domain.ConsentDefinition;
import si.konferenca.registration.domain.FieldErrors;
import si.konferenca.registration.domain.OptionCategory;
import si.konferenca.registration.domain.RegistrationSubmission;
import si.konferenca.registration.domain.RegistrationType;
import si.konferenca.registration.export.RegistrationExport;
import si.konferenca.registration.service.RegistrationRejectedException;

class WebLayerTest {

  private final ApiExceptionHandler handler = new ApiExceptionHandler();

  private static void assertError(
      ResponseEntity<ErrorResponse> response, HttpStatus status, String message) {
    assertThat(response.getStatusCode()).isEqualTo(status);
    assertThat(response.getBody()).isEqualTo(new ErrorResponse(message, Map.of()));
  }

  @Test
  void errorModelForEveryFailure() {
    FieldErrors errors = new FieldErrors();
    errors.add("email", "Enter a valid email address.");
    ResponseEntity<ErrorResponse> rejected =
        handler.rejected(new RegistrationRejectedException(errors));
    assertThat(rejected.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
    assertThat(rejected.getBody())
        .isEqualTo(
            new ErrorResponse(
                "Please correct the marked fields.", Map.of("email", "Enter a valid email address.")));

    assertError(
        handler.unreadable(
            new HttpMessageNotReadableException("x", new MockHttpInputMessage(new byte[0]))),
        HttpStatus.BAD_REQUEST,
        "The request could not be read.");
    assertError(
        handler.unsupportedMediaType(new HttpMediaTypeNotSupportedException("text/plain")),
        HttpStatus.UNSUPPORTED_MEDIA_TYPE,
        "The request could not be read.");
    assertError(
        handler.methodNotAllowed(new HttpRequestMethodNotSupportedException("PUT")),
        HttpStatus.METHOD_NOT_ALLOWED,
        "The request could not be read.");
    assertError(
        handler.notFound(new NoResourceFoundException(HttpMethod.GET, "/api/x", "x")),
        HttpStatus.NOT_FOUND,
        "Not found.");
    assertError(
        handler.unexpected(new IllegalStateException("SELECT secret FROM table")),
        HttpStatus.INTERNAL_SERVER_ERROR,
        "The registration could not be completed. Please try again later.");
  }

  @Test
  void errorResponseCopiesFieldErrors() {
    Map<String, String> fields = new HashMap<>(Map.of("a", "b"));
    ErrorResponse response = new ErrorResponse("m", fields);
    fields.put("c", "d");
    assertThat(response.fieldErrors()).containsExactly(Map.entry("a", "b"));
    assertThat(ErrorResponse.of("m").fieldErrors()).isEmpty();
  }

  @Test
  void formConfigListsActiveOptionsWithSortedTypesAndHidesSiteKeyInTestMode() {
    ConferenceCatalog catalog =
        new ConferenceCatalog(
            List.of(
                new ConferenceOption(
                    "a", "A", OptionCategory.EVENT, true, EnumSet.of(RegistrationType.STUDENT, RegistrationType.EXTERNAL)),
                new ConferenceOption("b", "B", OptionCategory.MEAL, false, EnumSet.of(RegistrationType.STUDENT))),
            List.of(new ConsentDefinition("privacy", "P", true)));

    FormConfigResponse live = FormConfigResponse.of("Konf", "site-key", false, catalog);
    FormConfigResponse test = FormConfigResponse.of("Konf", "site-key", true, catalog);

    assertThat(live.conferenceName()).isEqualTo("Konf");
    assertThat(live.recaptchaSiteKey()).isEqualTo("site-key");
    assertThat(live.recaptchaTestMode()).isFalse();
    assertThat(live.consents()).containsExactly(new FormConfigResponse.Consent("privacy", "P", true));
    assertThat(live.options())
        .containsExactly(
            new FormConfigResponse.Option(
                "a", "A", OptionCategory.EVENT, List.of(RegistrationType.EXTERNAL, RegistrationType.STUDENT)));
    assertThat(test.recaptchaSiteKey()).isEmpty();
    assertThat(test.recaptchaTestMode()).isTrue();
    assertThatThrownBy(() -> live.options().clear()).isInstanceOf(UnsupportedOperationException.class);
  }

  @Test
  void requestMapsToSubmissionWithCopiedLists() {
    List<String> options = new ArrayList<>(List.of("ws"));
    RegistrationRequest request =
        new RegistrationRequest(
            "STUDENT", "A", "B", "e@x.co", null, "U", "P", "1", options, List.of("privacy"), "tok");
    options.add("late");

    RegistrationSubmission submission = request.toSubmission();

    assertThat(submission)
        .isEqualTo(
            new RegistrationSubmission(
                "STUDENT", "A", "B", "e@x.co", null, "U", "P", "1", List.of("ws"), List.of("privacy")));
    assertThat(request.recaptchaToken()).isEqualTo("tok");
    RegistrationRequest empty =
        new RegistrationRequest(null, null, null, null, null, null, null, null, null, null, null);
    assertThat(empty.optionIds()).isNull();
    assertThat(empty.consents()).isNull();
  }

  @Test
  void exportIsAnAttachmentThatIsNotCached() {
    RegistrationExport export = mock(RegistrationExport.class);
    when(export.workbook()).thenReturn(new byte[] {80, 75});

    ResponseEntity<byte[]> response = new ExportController(export).registrations();

    assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);
    assertThat(response.getBody()).containsExactly(80, 75);
    assertThat(response.getHeaders().getContentType())
        .hasToString("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    assertThat(response.getHeaders().getFirst("Content-Disposition"))
        .isEqualTo("attachment; filename=\"registrations.xlsx\"");
    assertThat(response.getHeaders().getCacheControl()).isEqualTo("no-store");
  }
}

package si.konferenca.registration.export;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.ByteArrayInputStream;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import org.apache.poi.ss.usermodel.Cell;
import org.apache.poi.ss.usermodel.CellType;
import org.apache.poi.ss.usermodel.Row;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.junit.jupiter.api.Test;
import si.konferenca.registration.domain.OptionCategory;
import si.konferenca.registration.domain.Registration;
import si.konferenca.registration.domain.RegistrationType;
import si.konferenca.registration.persistence.RegistrationStore;

class RegistrationExportTest {

  static final Instant AT = Instant.parse("2026-10-13T08:00:00.120Z");

  static Registration external(String firstName) {
    return new Registration(
        UUID.fromString("6f1c1b7e-2f7a-4c55-9d0e-3c1f7c2b9a10"),
        AT,
        RegistrationType.EXTERNAL,
        firstName,
        "Novak",
        "a@b.co",
        "Acme",
        null,
        null,
        null,
        List.of(
            new Registration.SelectedOption("ws", "Workshop", OptionCategory.WORKSHOP),
            new Registration.SelectedOption("ml", "Lunch", OptionCategory.MEAL)),
        List.of(
            new Registration.GivenConsent("privacy", "P", AT),
            new Registration.GivenConsent("photos", "F", AT)));
  }

  static Registration student() {
    return new Registration(
        UUID.fromString("00000000-0000-0000-0000-000000000002"),
        AT,
        RegistrationType.STUDENT,
        "Bor",
        "Kranjc",
        "b@c.co",
        null,
        "Uni",
        "CS",
        "123",
        List.of(),
        List.of());
  }

  @Test
  void rowHasEveryColumnInHeaderOrder() {
    assertThat(RegistrationExport.row(external("Ana")))
        .containsExactly(
            "6f1c1b7e-2f7a-4c55-9d0e-3c1f7c2b9a10",
            "EXTERNAL",
            "2026-10-13T08:00:00.120Z",
            "Ana",
            "Novak",
            "a@b.co",
            "Acme",
            "",
            "",
            "",
            "Workshop; Lunch",
            "privacy given 2026-10-13T08:00:00.120Z; photos given 2026-10-13T08:00:00.120Z");
    assertThat(RegistrationExport.row(student()))
        .containsExactly(
            "00000000-0000-0000-0000-000000000002",
            "STUDENT",
            "2026-10-13T08:00:00.120Z",
            "Bor",
            "Kranjc",
            "b@c.co",
            "",
            "Uni",
            "CS",
            "123",
            "",
            "");
    assertThat(RegistrationExport.HEADER).hasSize(12);
  }

  @Test
  void workbookHasHeaderAndOneStringRowPerRegistration() throws Exception {
    RegistrationStore store = mock(RegistrationStore.class);
    when(store.findAllInOrder()).thenReturn(List.of(external("=1+1"), student()));

    byte[] bytes = new RegistrationExport(store).workbook();

    try (XSSFWorkbook book = new XSSFWorkbook(new ByteArrayInputStream(bytes))) {
      assertThat(book.getNumberOfSheets()).isEqualTo(1);
      Sheet sheet = book.getSheet("Registrations");
      assertThat(sheet.getPhysicalNumberOfRows()).isEqualTo(3);
      assertThat(values(sheet.getRow(0))).isEqualTo(RegistrationExport.HEADER);
      assertThat(values(sheet.getRow(1))).isEqualTo(RegistrationExport.row(external("=1+1")));
      assertThat(values(sheet.getRow(2))).isEqualTo(RegistrationExport.row(student()));
      for (Cell cell : sheet.getRow(1)) {
        assertThat(cell.getCellType()).isEqualTo(CellType.STRING);
      }
    }
  }

  @Test
  void emptyExportHasOnlyTheHeader() throws Exception {
    RegistrationStore store = mock(RegistrationStore.class);
    when(store.findAllInOrder()).thenReturn(List.of());

    try (XSSFWorkbook book =
        new XSSFWorkbook(new ByteArrayInputStream(new RegistrationExport(store).workbook()))) {
      assertThat(book.getSheetAt(0).getPhysicalNumberOfRows()).isEqualTo(1);
    }
  }

  private static List<String> values(Row row) {
    List<String> values = new ArrayList<>();
    for (Cell cell : row) {
      values.add(cell.getStringCellValue());
    }
    return values;
  }
}

package si.konferenca.registration.persistence;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.Instant;
import java.util.List;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import si.konferenca.registration.domain.OptionCategory;
import si.konferenca.registration.domain.Registration;
import si.konferenca.registration.domain.RegistrationType;

class RegistrationStoreTest {

  static final Instant AT = Instant.parse("2026-10-13T08:00:00.120Z");
  static final Registration STUDENT =
      new Registration(
          UUID.randomUUID(),
          AT,
          RegistrationType.STUDENT,
          "Bor",
          "Kranjc",
          "b@c.co",
          null,
          "Uni",
          "CS",
          "123",
          List.of(new Registration.SelectedOption("ws", "W", OptionCategory.WORKSHOP)),
          List.of(new Registration.GivenConsent("privacy", "P", AT)));

  private final RegistrationRepository repository = mock(RegistrationRepository.class);
  private final RegistrationStore store = new RegistrationStore(repository);

  @Test
  void insertMapsEveryFieldAndFlushes() {
    store.insert(STUDENT);

    ArgumentCaptor<RegistrationEntity> captor = ArgumentCaptor.forClass(RegistrationEntity.class);
    verify(repository).saveAndFlush(captor.capture());
    RegistrationEntity e = captor.getValue();
    assertThat(e.id()).isEqualTo(STUDENT.id());
    assertThat(e.type()).isEqualTo(RegistrationType.STUDENT);
    assertThat(e.firstName()).isEqualTo("Bor");
    assertThat(e.lastName()).isEqualTo("Kranjc");
    assertThat(e.email()).isEqualTo("b@c.co");
    assertThat(e.organization()).isNull();
    assertThat(e.studyInstitution()).isEqualTo("Uni");
    assertThat(e.studyProgramme()).isEqualTo("CS");
    assertThat(e.studentId()).isEqualTo("123");
    assertThat(e.registeredAt()).isEqualTo(AT);
    assertThat(e.options()).singleElement()
        .satisfies(
            o -> {
              assertThat(o.optionId()).isEqualTo("ws");
              assertThat(o.optionName()).isEqualTo("W");
              assertThat(o.optionCategory()).isEqualTo(OptionCategory.WORKSHOP);
            });
    assertThat(e.consents()).singleElement()
        .satisfies(
            c -> {
              assertThat(c.consentId()).isEqualTo("privacy");
              assertThat(c.consentText()).isEqualTo("P");
              assertThat(c.givenAt()).isEqualTo(AT);
            });
  }

  @Test
  void findAllMapsEntitiesBackInRepositoryOrder() {
    store.insert(STUDENT);
    ArgumentCaptor<RegistrationEntity> captor = ArgumentCaptor.forClass(RegistrationEntity.class);
    verify(repository).saveAndFlush(captor.capture());
    RegistrationEntity external =
        new RegistrationEntity(
            UUID.randomUUID(),
            RegistrationType.EXTERNAL,
            "Ana",
            "Novak",
            "a@b.co",
            "Org",
            null,
            null,
            null,
            AT.plusSeconds(1),
            List.of(),
            List.of());
    when(repository.findAllByOrderByRegisteredAtAsc()).thenReturn(List.of(captor.getValue(), external));

    List<Registration> all = store.findAllInOrder();

    assertThat(all.get(0)).isEqualTo(STUDENT);
    assertThat(all.get(1).organization()).isEqualTo("Org");
    assertThat(all.get(1).type()).isEqualTo(RegistrationType.EXTERNAL);
    assertThat(all.get(1).options()).isEmpty();
  }

  @Test
  void jpaConstructorsExistForHibernate() {
    assertThat(new RegistrationEntity().options()).isEmpty();
    assertThat(new RegistrationEntity.OptionRow().optionId()).isNull();
    assertThat(new RegistrationEntity.ConsentRow().consentId()).isNull();
  }
}

package si.konferenca.registration;

import static org.assertj.core.api.Assertions.assertThat;

import java.net.URI;
import java.util.Arrays;
import java.util.List;
import org.junit.jupiter.api.Test;

class RegistrationPropertiesTest {

  @Test
  void recipientsAndOriginsAreStrippedWithoutBlanks() {
    assertThat(
            new RegistrationProperties.Mail("f", Arrays.asList(" a@b.co ", "", "  ", "c@d.co"))
                .organizerRecipients())
        .containsExactly("a@b.co", "c@d.co");
    assertThat(new RegistrationProperties.Mail("f", null).organizerRecipients()).isEmpty();
    assertThat(new RegistrationProperties.Cors(List.of(" http://x ", " ")).allowedOrigins())
        .containsExactly("http://x");
    assertThat(new RegistrationProperties.Cors(null).allowedOrigins()).isEmpty();
  }

  @Test
  void secretsAreNotPrinted() {
    assertThat(new RegistrationProperties.Organizer("boss", "pw-123456", true).toString())
        .isEqualTo("Organizer[httpsOnly=true]");
    assertThat(
            new RegistrationProperties.Recaptcha(false, "site", "secret-123456", URI.create("http://v"))
                .toString())
        .isEqualTo("Recaptcha[testMode=false, verifyUrl=http://v]");
  }
}

package si.konferenca.registration.architecture;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;
import static com.tngtech.archunit.library.dependencies.SlicesRuleDefinition.slices;

import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

/** The architecture declared in docs/02_specification.md section 2 (AR-02, AR-03, DoD-04). */
class ArchitectureTest {

  private static final String ROOT = "si.konferenca.registration";
  private static final JavaClasses CLASSES =
      new ClassFileImporter()
          .withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
          .importPackages(ROOT);

  private static final List<String> PACKAGES =
      List.of(
          "domain", "catalog", "service", "persistence", "storage", "mail", "captcha", "export",
          "security", "web");

  /** Spec 2: the application packages each package may depend on (besides itself and root). */
  private static final Map<String, List<String>> ALLOWED =
      Map.of(
          "domain", List.of(),
          "catalog", List.of("domain"),
          "service", List.of("domain", "persistence"),
          "persistence", List.of("domain"),
          "storage", List.of("domain", "service"),
          "mail", List.of("domain", "service"),
          "captcha", List.of("domain", "service"),
          "export", List.of("domain", "persistence"),
          "security", List.of("domain"),
          "web", List.of("domain", "catalog", "service", "export"));

  @Test
  void domainIsPlainJava() {
    noClasses()
        .that()
        .resideInAPackage(ROOT + ".domain..")
        .should()
        .dependOnClassesThat()
        .resideInAnyPackage(
            "org.springframework..", "jakarta.persistence..", "tools.jackson..", ROOT)
        .check(CLASSES);
  }

  @Test
  void eachPackageDependsOnlyOnItsDeclaredPackages() {
    for (String pkg : PACKAGES) {
      String[] forbidden =
          PACKAGES.stream()
              .filter(other -> !other.equals(pkg) && !ALLOWED.get(pkg).contains(other))
              .map(other -> ROOT + "." + other + "..")
              .toArray(String[]::new);
      noClasses()
          .that()
          .resideInAPackage(ROOT + "." + pkg + "..")
          .should()
          .dependOnClassesThat()
          .resideInAnyPackage(forbidden)
          .because("spec section 2 allows " + pkg + " to use only " + ALLOWED.get(pkg))
          .check(CLASSES);
    }
  }

  @Test
  void nothingDependsOnTheWebLayer() {
    noClasses()
        .that()
        .resideOutsideOfPackage(ROOT + ".web..")
        .and()
        .resideOutsideOfPackage(ROOT)
        .should()
        .dependOnClassesThat()
        .resideInAPackage(ROOT + ".web..")
        .check(CLASSES);
  }

  @Test
  void serviceUsesSideEffectsOnlyThroughPorts() {
    noClasses()
        .that()
        .resideInAPackage(ROOT + ".service..")
        .should()
        .dependOnClassesThat()
        .resideInAnyPackage(ROOT + ".storage..", ROOT + ".mail..", ROOT + ".captcha..")
        .check(CLASSES);
  }

  @Test
  void noPackageCycles() {
    slices().matching(ROOT + ".(*)..").should().beFreeOfCycles().check(CLASSES);
  }
}

